<?php
declare(strict_types=1);
session_start();
require_once __DIR__ . '/config.php';
require_once __DIR__ . '/functions.php';
$db = db();
$site = setting($db, 'site_name', 'SOUND');
$tagline = setting($db, 'tagline', 'A world of music, made for discovery.');
$about = setting($db, 'about_text', 'SOUND is your destination to discover songs and videos across languages, eras, artists and genres. Find a favourite, share your thoughts and explore something new.');
$action = $_POST['action'] ?? '';
$flash = '';
$errors = [];

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf();
    try {
        if ($action === 'register') {
            $username = trim((string)($_POST['username'] ?? ''));
            $name = trim((string)($_POST['name'] ?? ''));
            $address = trim((string)($_POST['address'] ?? ''));
            $phone = trim((string)($_POST['phone'] ?? ''));
            $email = trim((string)($_POST['email'] ?? ''));
            $password = (string)($_POST['password'] ?? '');
            if (!preg_match('/^[a-zA-Z0-9_.-]{4,30}$/', $username)) throw new RuntimeException('User ID must be 4–30 characters and may contain letters, numbers, dots, underscores or hyphens.');
            if ($name === '' || $address === '' || $phone === '' || $email === '' || $password === '') throw new RuntimeException('Please complete every required field.');
            if (!filter_var($email, FILTER_VALIDATE_EMAIL)) throw new RuntimeException('Please enter a valid email address.');
            if (!preg_match('/^[0-9+\-\s()]{7,20}$/', $phone)) throw new RuntimeException('Please enter a valid phone number.');
            if (strlen($password) < 8) throw new RuntimeException('Password must be at least 8 characters.');
            $stmt = $db->prepare("INSERT INTO users (username,name,address,phone,email,password_hash,role) VALUES (?,?,?,?,?,?, 'user')");
            try { $stmt->execute([$username,$name,$address,$phone,$email,password_hash($password, PASSWORD_DEFAULT)]); }
            catch (PDOException $e) { if ((string)$e->getCode()==='23000') throw new RuntimeException('That User ID or email is already registered. Please choose another.'); throw $e; }
            $_SESSION['user_id'] = (int)$db->lastInsertId();
            session_regenerate_id(true);
            redirect('index.php?route=account');
        } elseif ($action === 'login') {
            $stmt = $db->prepare('SELECT * FROM users WHERE username = ? OR email = ? LIMIT 1');
            $identity = trim((string)($_POST['identity'] ?? ''));
            $stmt->execute([$identity,$identity]); $user = $stmt->fetch();
            if (!$user || !password_verify((string)($_POST['password'] ?? ''), $user['password_hash'])) throw new RuntimeException('Incorrect User ID/email or password.');
            if ((int)$user['is_active'] !== 1) throw new RuntimeException('This account is inactive. Please contact the administrator.');
            session_regenerate_id(true); $_SESSION['user_id'] = (int)$user['id'];
            redirect('index.php?route=' . ($user['role']==='admin' ? 'admin' : 'account'));
        } elseif ($action === 'logout') {
            $_SESSION = []; session_destroy(); redirect('index.php');
        } elseif ($action === 'review') {
            $user = require_user($db);
            $mediaId = (int)($_POST['media_id'] ?? 0); $rating = (int)($_POST['rating'] ?? 0);
            $review = trim((string)($_POST['review_text'] ?? ''));
            if ($rating < 1 || $rating > 5) throw new RuntimeException('Please choose a rating from 1 to 5 stars.');
            if (mb_strlen($review) > 1200) throw new RuntimeException('Review must be under 1,200 characters.');
            $check=$db->prepare('SELECT id FROM media_items WHERE id=?');$check->execute([$mediaId]);if(!$check->fetch())throw new RuntimeException('This item is not available.');
            $stmt=$db->prepare('INSERT INTO reviews (user_id,media_id,rating,review_text) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE rating=VALUES(rating), review_text=VALUES(review_text), updated_at=CURRENT_TIMESTAMP');
            $stmt->execute([$user['id'],$mediaId,$rating,$review]); redirect('index.php?route=detail&id='.$mediaId.'#reviews');
        } elseif ($action === 'admin_media_save') {
            $admin = require_admin($db);
            $id=(int)($_POST['id']??0); $type=$_POST['type']??'music';
            if(!in_array($type,['music','video'],true))throw new RuntimeException('Choose a valid media type.');
            $title=trim((string)($_POST['title']??''));$artist=trim((string)($_POST['artist']??''));$album=trim((string)($_POST['album']??''));
            $year=(int)($_POST['release_year']??0);$genre=trim((string)($_POST['genre']??''));$language=trim((string)($_POST['language']??''));$description=trim((string)($_POST['description']??''));
            if($title===''||$artist===''||$album===''||$year<1900||$year>(int)date('Y')+2||$genre===''||$language===''||$description==='')throw new RuntimeException('Complete all required media information and enter a valid release year.');
            $cover=upload_file('cover','covers',['jpg','jpeg','png','webp']);$media=upload_file('media_file','media',$type==='music'?['mp3','wav','ogg','m4a','aac','flac','mp4','webm','mov']:['mp4','webm','ogv','mov','m4v']);
            if($id>0){
                $old=$db->prepare('SELECT cover_path,media_path FROM media_items WHERE id=?');$old->execute([$id]);$prev=$old->fetch();if(!$prev)throw new RuntimeException('Media item not found.');
                $cover=$cover?:$prev['cover_path'];$media=$media?:$prev['media_path'];
                $st=$db->prepare('UPDATE media_items SET type=?,title=?,artist=?,album=?,release_year=?,genre=?,language=?,description=?,cover_path=?,media_path=?,is_new=?,updated_at=CURRENT_TIMESTAMP WHERE id=?');
                $st->execute([$type,$title,$artist,$album,$year,$genre,$language,$description,$cover,$media,isset($_POST['is_new'])?1:0,$id]);
            }else{
                $st=$db->prepare('INSERT INTO media_items (type,title,artist,album,release_year,genre,language,description,cover_path,media_path,is_new) VALUES (?,?,?,?,?,?,?,?,?,?,?)');
                $st->execute([$type,$title,$artist,$album,$year,$genre,$language,$description,$cover,$media,isset($_POST['is_new'])?1:0]);
            }
            redirect('index.php?route=admin&tab=media&saved=1');
        } elseif ($action === 'admin_media_delete') {
            require_admin($db);$id=(int)($_POST['id']??0);$db->prepare('DELETE FROM media_items WHERE id=?')->execute([$id]);redirect('index.php?route=admin&tab=media&deleted=1');
        } elseif ($action === 'category_save') {
            require_admin($db);$type=trim((string)($_POST['category_type']??''));$name=trim((string)($_POST['category_name']??''));
            $allowed=['Artist','Album','Year','Genre','Language'];
            if(!in_array($type,$allowed,true)||$name==='')throw new RuntimeException('Choose a category type and enter its name.');
            $st=$db->prepare('INSERT IGNORE INTO categories (category_type,category_name) VALUES (?,?)');$st->execute([$type,$name]);redirect('index.php?route=admin&tab=categories&saved=1');
        } elseif ($action === 'category_delete') {
            require_admin($db);$db->prepare('DELETE FROM categories WHERE id=?')->execute([(int)$_POST['id']]);redirect('index.php?route=admin&tab=categories');
        } elseif ($action === 'user_update') {
            require_admin($db);$id=(int)($_POST['id']??0);$role=$_POST['role']??'user';$active=isset($_POST['is_active'])?1:0;
            if(!in_array($role,['admin','user'],true))throw new RuntimeException('Invalid role.');
            if($id===(int)($_SESSION['user_id']??0)&&$active===0)throw new RuntimeException('You cannot deactivate your own account.');
            $db->prepare('UPDATE users SET role=?,is_active=? WHERE id=?')->execute([$role,$active,$id]);redirect('index.php?route=admin&tab=users&saved=1');
        } elseif ($action === 'settings_save') {
            require_admin($db);foreach(['site_name','tagline','about_text'] as $key){$value=trim((string)($_POST[$key]??''));if($value==='')throw new RuntimeException('Site name, tagline and about text are required.');$st=$db->prepare('INSERT INTO settings (setting_key,setting_value) VALUES (?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');$st->execute([$key,$value]);}redirect('index.php?route=admin&tab=settings&saved=1');
        }
    } catch (Throwable $e) { $errors[] = $e instanceof RuntimeException ? $e->getMessage() : 'Something went wrong. Check the input and database setup, then try again.'; }
}

$route = $_GET['route'] ?? 'home';
$currentUser = current_user($db);
if ($route === 'admin' && (!$currentUser || $currentUser['role']!=='admin')) { $route='login'; $errors[]='Please sign in with an administrator account to open the dashboard.'; }
function page_header(string $title, string $site, string $route, ?array $user): void {
    echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'.h($title).' · '.h($site).'</title><link rel="stylesheet" href="assets/style.css"></head><body><div class="topline"></div><header class="navwrap"><div class="shell nav"><a class="brand" href="index.php"><span class="brand-mark">♫</span><span>'.h($site).'<small>ENTERTAINMENT, IN EVERY NOTE</small></span></a><nav class="navlinks"><a class="'.($route==='home'?'active':'').'" href="index.php">Home</a><a class="'.($route==='browse'?'active':'').'" href="index.php?route=browse">Explore</a><a href="index.php?route=browse&type=music">Music</a><a href="index.php?route=browse&type=video">Videos</a><a href="index.php?route=about">About</a></nav><div class="navright">';
    if($user){echo '<a class="btn light" href="index.php?route=account">'.h($user['name']).'</a>';if($user['role']==='admin')echo '<a class="btn small" href="index.php?route=admin">Admin</a>';echo '<form method="post" style="display:inline">'.csrf_field().'<input type="hidden" name="action" value="logout"><button class="btn dark small">Sign out</button></form>';}
    else echo '<a class="btn light" href="index.php?route=login">Sign in</a><a class="btn small" href="index.php?route=register">Join SOUND ↗</a>';
    echo '</div></div></header><main class="shell">';
}
function page_footer(string $site): void {echo '</main><footer class="footer"><div class="shell"><div class="footer-grid"><div><div class="brand"><span class="brand-mark">♫</span><span>'.h($site).'<small>ENTERTAINMENT, IN EVERY NOTE</small></span></div><p style="max-width:330px">A thoughtful home for songs, videos and the stories behind them. Browse by artist, album, year, genre and language.</p></div><div><h4>EXPLORE</h4><p><a href="index.php?route=browse&type=music">Music library</a><br><a href="index.php?route=browse&type=video">Video library</a><br><a href="index.php?route=about">About the project</a></p></div><div><h4>YOUR ACCOUNT</h4><p><a href="index.php?route=register">Create an account</a><br><a href="index.php?route=login">Sign in</a><br><a href="index.php?route=admin">Administration</a></p></div></div><div class="footer-bottom"><span>© '.date('Y').' '.h($site).' · Student eProject</span><span>Built for discovery. Powered by PHP & MySQL.</span></div></div></footer><script src="assets/app.js"></script></body></html>';}
function flash_messages(array $errors): void {foreach($errors as $e)echo '<div class="alert error">'.h($e).'</div>';if(isset($_GET['saved']))echo '<div class="alert success">Changes saved successfully.</div>';if(isset($_GET['deleted']))echo '<div class="alert success">Item deleted successfully.</div>';}
function media_card(array $m): void {
    $colors=['pink','blue','green','orange','lilac','navy','cream','red','teal','gray'];$color=$colors[((int)$m['id']-1)%count($colors)];
    $symbol=$m['type']==='video'?'▶': '♫';$avg=$m['avg_rating']??null;
    echo '<article class="media-card"><a href="index.php?route=detail&id='.(int)$m['id'].'"><div class="cover '.$color.'">';
    if(!empty($m['cover_path']))echo '<img src="'.h($m['cover_path']).'" alt="" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:-1">';
    echo '<span class="cover-symbol">'.h($symbol).'</span>';if(!empty($m['is_new']))echo '<span class="new">✦ NEW</span>';echo '<button class="playcover" type="button" aria-label="View details">↗</button></div></a><div class="media-info"><h3><a href="index.php?route=detail&id='.(int)$m['id'].'">'.h($m['title']).'</a></h3><p>'.h($m['artist']).' · '.h($m['release_year']).' · '.h($m['language']).'</p><div class="rating">★ '.($avg!==null?number_format((float)$avg,1):'New').'<span>('.(int)($m['review_count']??0).' reviews)</span></div></div></article>';
}
page_header($route==='home'?$site.' — Discover music & videos':ucfirst($route),$site,$route,$currentUser);
flash_messages($errors);

if ($route === 'home') {
    $latestMusic=$db->query("SELECT m.*, AVG(r.rating) avg_rating, COUNT(r.id) review_count FROM media_items m LEFT JOIN reviews r ON r.media_id=m.id WHERE m.type='music' GROUP BY m.id ORDER BY m.created_at DESC,m.id DESC LIMIT 5")->fetchAll();
    $latestVideos=$db->query("SELECT m.*, AVG(r.rating) avg_rating, COUNT(r.id) review_count FROM media_items m LEFT JOIN reviews r ON r.media_id=m.id WHERE m.type='video' GROUP BY m.id ORDER BY m.created_at DESC,m.id DESC LIMIT 5")->fetchAll();
    echo '<section class="hero"><div><div class="eyebrow">A BETTER WAY TO DISCOVER</div><h1>Every sound has a <em>story.</em></h1><p>'.h($about).'</p><div class="hero-actions"><a class="btn" href="index.php?route=browse">Explore the library ↗</a><a class="btn light" href="index.php?route=browse&type=video">Watch videos</a></div><div class="hero-meta"><span><b>01</b> · Music & video</span><span><b>02</b> · Regional & English</span><span><b>03</b> · Your reviews</span></div></div><div class="hero-art"><div class="art-top"><span>THE SOUND OF DISCOVERY</span><span class="live"><i></i> CURATED FOR YOU</span></div><div class="record"><div class="orbit"></div><div class="disc" id="heroDisc"><div class="disc-center">♫</div></div></div><div class="art-bottom"><div><h3>Listen beyond the usual.</h3><p>Old favourites. New discoveries. One place.</p></div><button class="art-play" id="discToggle" aria-label="Pause animation">Ⅱ</button></div></div></section>';
    echo '<section class="section"><div class="section-head"><div><div class="eyebrow">FRESHLY ADDED</div><h2>Latest music</h2><p>New tracks and timeless favourites, all in one place.</p></div><a class="textlink" href="index.php?route=browse&type=music">Explore all music ↗</a></div>';
    if($latestMusic){echo '<div class="cards">';foreach($latestMusic as $m)media_card($m);echo '</div>';}else echo '<div class="empty">Your music library is waiting. Add songs from the admin dashboard.</div>';
    echo '</section><section class="section" style="padding-top:15px"><div class="section-head"><div><div class="eyebrow">ON THE SCREEN</div><h2>Latest videos</h2><p>Discover music videos and entertainment from different eras.</p></div><a class="textlink" href="index.php?route=browse&type=video">Explore all videos ↗</a></div>';
    if($latestVideos){echo '<div class="cards">';foreach($latestVideos as $m)media_card($m);echo '</div>';}else echo '<div class="empty">Your video library is waiting. Add videos from the admin dashboard.</div>';
    echo '</section><section class="section"><div class="feature-band"><div><div class="eyebrow">MADE FOR MUSIC LOVERS</div><h2>Find your next favourite.</h2><p>Search by artist, album, release year, genre or language. Rate what you love and leave a review to help other listeners discover something special.</p><a class="btn dark" href="index.php?route=browse">Start exploring ↗</a></div><div class="feature-points"><div class="feature-point"><b>♫ Curated library</b><span>Music and videos in one place</span></div><div class="feature-point"><b>✦ Discover by detail</b><span>Artist, album, year and genre</span></div><div class="feature-point"><b>★ Community reviews</b><span>Share honest ratings</span></div><div class="feature-point"><b>◎ Regional + English</b><span>Different languages and eras</span></div></div></div></section>';
} elseif ($route === 'browse') {
    $q=trim((string)($_GET['q']??''));$type=$_GET['type']??'';$genre=trim((string)($_GET['genre']??''));$language=trim((string)($_GET['language']??''));$year=trim((string)($_GET['year']??''));
    $sql="SELECT m.*,AVG(r.rating) avg_rating,COUNT(r.id) review_count FROM media_items m LEFT JOIN reviews r ON r.media_id=m.id WHERE 1=1";$args=[];
    if(in_array($type,['music','video'],true)){$sql.=' AND m.type=?';$args[]=$type;}
    if($q!==''){$sql.=" AND (m.title LIKE ? OR m.artist LIKE ? OR m.album LIKE ? OR m.genre LIKE ? OR m.language LIKE ? OR CAST(m.release_year AS CHAR) LIKE ?)";foreach(range(1,6) as $x)$args[]='%'.$q.'%';}
    if($genre!==''){$sql.=' AND m.genre=?';$args[]=$genre;}if($language!==''){$sql.=' AND m.language=?';$args[]=$language;}if($year!==''){$sql.=' AND m.release_year=?';$args[]=(int)$year;}
    $sql.=' GROUP BY m.id ORDER BY m.is_new DESC,m.created_at DESC,m.title ASC';$st=$db->prepare($sql);$st->execute($args);$items=$st->fetchAll();
    $genres=$db->query('SELECT DISTINCT genre FROM media_items WHERE genre<>"" ORDER BY genre')->fetchAll(PDO::FETCH_COLUMN);$languages=$db->query('SELECT DISTINCT language FROM media_items WHERE language<>"" ORDER BY language')->fetchAll(PDO::FETCH_COLUMN);$years=$db->query('SELECT DISTINCT release_year FROM media_items ORDER BY release_year DESC')->fetchAll(PDO::FETCH_COLUMN);
    echo '<section class="section"><div class="section-head"><div><div class="eyebrow">THE FULL COLLECTION</div><h2>Explore the library</h2><p>Filter by format, language, genre or year — or search for a specific title.</p></div><span class="chip">'.count($items).' results</span></div><div class="browse-layout"><form class="filters" method="get"><input type="hidden" name="route" value="browse"><h3>Refine your search</h3><div class="field"><label>Search everything</label><input name="q" value="'.h($q).'" placeholder="Song, artist, album..."></div><div class="field"><label>Format</label><select name="type"><option value="">Music & videos</option><option value="music" '.($type==='music'?'selected':'').'>Music</option><option value="video" '.($type==='video'?'selected':'').'>Videos</option></select></div><div class="field"><label>Genre</label><select name="genre"><option value="">All genres</option>';foreach($genres as $g)echo '<option '.($genre===$g?'selected':'').' value="'.h($g).'">'.h($g).'</option>';echo '</select></div><div class="field"><label>Language</label><select name="language"><option value="">All languages</option>';foreach($languages as $l)echo '<option '.($language===$l?'selected':'').' value="'.h($l).'">'.h($l).'</option>';echo '</select></div><div class="field"><label>Release year</label><select name="year"><option value="">Any year</option>';foreach($years as $y)echo '<option '.((string)$year===(string)$y?'selected':'').' value="'.(int)$y.'">'.(int)$y.'</option>';echo '</select></div><button class="btn" style="width:100%">Apply filters</button><a class="btn light" style="width:100%;margin-top:8px" href="index.php?route=browse">Clear filters</a></form><div>';
    if($items){echo '<div class="cards">';foreach($items as $m)media_card($m);echo '</div>';}else echo '<div class="empty"><div style="font-size:32px;margin-bottom:10px">⌕</div><b>No results found</b><p>Try another title, artist, language or filter.</p></div>';echo '</div></div></section>';
} elseif ($route === 'detail') {
    $id=(int)($_GET['id']??0);$st=$db->prepare('SELECT m.*,AVG(r.rating) avg_rating,COUNT(r.id) review_count FROM media_items m LEFT JOIN reviews r ON r.media_id=m.id WHERE m.id=? GROUP BY m.id');$st->execute([$id]);$m=$st->fetch();
    if(!$m){echo '<div class="empty" style="margin:50px 0">This item could not be found. <a class="textlink" href="index.php?route=browse">Return to the library</a></div>';}else{
        $colors=['pink','blue','green','orange','lilac','navy','cream','red','teal','gray'];$color=$colors[((int)$m['id']-1)%count($colors)];
        echo '<section class="section"><a class="textlink" href="index.php?route=browse">← Back to library</a><div class="detail-grid" style="margin-top:22px"><div class="detail-cover '.$color.'">';if($m['cover_path'])echo '<img src="'.h($m['cover_path']).'" alt="" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover">';echo '<span style="z-index:1">'.($m['type']==='video'?'▶':'♫').'</span>';if($m['is_new'])echo '<span class="new" style="position:absolute;top:16px;left:16px">✦ NEW</span>';echo '</div><div class="detail-copy"><div class="eyebrow">'.($m['type']==='video'?'VIDEO':'MUSIC').' · '.h($m['language']).'</div><h1>'.h($m['title']).'</h1><p class="muted">By <b>'.h($m['artist']).'</b> · '.h($m['release_year']).'</p><div class="rating" style="font-size:14px">★ '.($m['avg_rating']!==null?number_format((float)$m['avg_rating'],1):'Not rated yet').' <span>('.(int)$m['review_count'].' reviews)</span></div><div class="detail-meta"><span>Album · '.h($m['album']).'</span><span>Genre · '.h($m['genre']).'</span><span>Year · '.h($m['release_year']).'</span></div><p class="desc">'.nl2br(h($m['description'])).'</p>';
        if($m['media_path']){if($m['type']==='video')echo '<video controls style="width:100%;max-height:360px;border-radius:15px;background:#111;margin-top:12px"><source src="'.h($m['media_path']).'"></video>';else echo '<audio controls style="width:100%;margin-top:12px" src="'.h($m['media_path']).'">Your browser does not support audio.</audio>';}else echo '<div class="notice">Media file has not been uploaded yet. The administrator can add the audio/video file from the dashboard.</div>';
        echo '</div></div><div id="reviews" style="margin-top:45px;display:grid;grid-template-columns:minmax(0,1fr) minmax(280px,.75fr);gap:35px"><div><div class="section-head"><div><div class="eyebrow">LISTENER NOTES</div><h2>Reviews & ratings</h2></div></div>';
        $rv=$db->prepare('SELECT r.*,u.name FROM reviews r JOIN users u ON u.id=r.user_id WHERE r.media_id=? ORDER BY r.updated_at DESC');$rv->execute([$id]);$reviews=$rv->fetchAll();if($reviews){foreach($reviews as $r)echo '<div class="review"><div class="review-head"><b>'.h($r['name']).'</b><span class="rating">'.str_repeat('★',(int)$r['rating']).str_repeat('☆',5-(int)$r['rating']).'</span></div><p>'.h($r['review_text']?:'Rated this item without a written review.').'</p><span class="muted">'.h(date('M j, Y',strtotime($r['updated_at']))).'</span></div>';}else echo '<div class="empty">No reviews yet. Be the first to share your thoughts.</div>';echo '</div><div class="content-card"><h2>Leave a review</h2><p class="muted">Your rating and review can be edited later from this page.</p>';
        if($currentUser && $currentUser['role']==='user'){$my=$db->prepare('SELECT * FROM reviews WHERE user_id=? AND media_id=?');$my->execute([$currentUser['id'],$id]);$mine=$my->fetch();echo '<form method="post">'.csrf_field().'<input type="hidden" name="action" value="review"><input type="hidden" name="media_id" value="'.$id.'"><div class="field"><label>Your rating *</label><select name="rating" required><option value="">Choose stars</option>';for($i=5;$i>=1;$i--)echo '<option value="'.$i.'" '.($mine&&(int)$mine['rating']===$i?'selected':'').'>'.$i.' star'.($i>1?'s':'').' '.str_repeat('★',$i).'</option>';echo '</select></div><div class="field"><label>Your review</label><textarea name="review_text" maxlength="1200" placeholder="What did you think?">'.h($mine['review_text']??'').'</textarea></div><button class="btn" style="width:100%">'.($mine?'Update my review':'Submit review').'</button></form>';}else echo '<div class="notice">Sign in with a user account to rate this item and write or update a review.</div><a class="btn" href="index.php?route=login">Sign in to review</a>';echo '</div></div></section>';
    }
} elseif ($route === 'register') {
