v class="field"><label>Cover image (JPG, PNG, WEBP)</label><input type="file" name="cover" accept=".jpg,.jpeg,.png,.webp"></div><div class="field"><label>'.(($edit['type']??'music')==='video'?'Video':'Audio').' file</label><input type="file" name="media_file" accept=".mp3,.wav,.ogg,.m4a,.aac,.flac,.mp4,.webm,.ogv,.mov,.m4v"></div></div><div class="field"><label>Description *</label><textarea name="description" required maxlength="5000">'.h($edit['description']??'').'</textarea></div><label style="display:flex;gap:8px;align-items:center;font-size:12px;margin-bottom:15px"><input type="checkbox" name="is_new" '.(!empty($edit['is_new'])?'checked':'').'> Mark as NEW (flashing badge)</label><button class="btn">'.($edit?'Save changes':'Add to library').' ↗</button>';if($edit)echo ' <a class="btn light" href="index.php?route=admin&tab=media">Cancel</a>';echo '</form></div>';
